"""Frozen paired seed/bank statistics for fine-range confirmation."""
import json
from pathlib import Path
import numpy as np
from .fine_range_common import OUT
from .confirmation_statistics import bootstrap_paired_difference
from .transformer_block_gpu import write_csv,save_json
def main():
    p=json.loads((OUT/'protocol.json').read_text());truth=np.load(OUT/'tokens.npz')['test_tokens'][:,1:];base=np.load(OUT/'baseline_tokens.npz');ref=base['FP32_nll'].astype(float).mean(-1);refac=(base['FP32_predictions']==truth).mean(-1);loss={};acc={};summary=[];draws={}
    for name in ['coarse','fine']:
        raw=[np.load(OUT/'runs'/f'{name}_seed{s}/prefix_tokens.npz') for s in p['sampling_seeds']];loss[name]=np.stack([v['prefix24_nll'].astype(float).mean(-1) for v in raw]);acc[name]=np.stack([(v['prefix24_predictions']==truth).mean(-1) for v in raw]);ce=bootstrap_paired_difference(loss[name],np.broadcast_to(ref,loss[name].shape),seed=p['bootstrap_seed']);ac=bootstrap_paired_difference(acc[name],np.broadcast_to(refac,acc[name].shape),seed=p['bootstrap_seed']);assert len(ce)==len(ac)==p['bootstrap_draws'];draws[name+'_CE_vs_FP32']=ce;draws[name+'_accuracy_vs_FP32']=ac;delta=float((loss[name]-ref).mean());ad=float((acc[name]-refac).mean());upper=float(np.quantile(ce,.975));lower=float(np.quantile(ac,.025));point=delta<=np.log(1.05) and ad>=-.01;summary.append({'condition':name,'cross_entropy':float(loss[name].mean()),'perplexity':float(np.exp(loss[name].mean())),'relative_perplexity':float(np.exp(delta)),'token_accuracy':float(acc[name].mean()),'accuracy_difference':ad,'point_passed':bool(point),'bootstrap_relative_upper':float(np.exp(upper)),'bootstrap_accuracy_lower':lower,'passes':bool(point and upper<=np.log(1.05) and lower>=-.01)})
    ce=bootstrap_paired_difference(loss['fine'],loss['coarse'],seed=p['bootstrap_seed']);ac=bootstrap_paired_difference(acc['fine'],acc['coarse'],seed=p['bootstrap_seed']);draws['paired_CE']=ce;draws['paired_accuracy']=ac;pair={'contrast':'fine-minus-coarse','CE_difference':float((loss['fine']-loss['coarse']).mean()),'perplexity_ratio':float(np.exp((loss['fine']-loss['coarse']).mean())),'accuracy_difference':float((acc['fine']-acc['coarse']).mean()),'CE_sensitivity_low':float(np.quantile(ce,.025)),'CE_sensitivity_high':float(np.quantile(ce,.975)),'accuracy_sensitivity_low':float(np.quantile(ac,.025)),'accuracy_sensitivity_high':float(np.quantile(ac,.975))};write_csv(OUT/'summary.csv',summary);save_json(OUT/'paired_summary.json',pair);np.savez_compressed(OUT/'quality_draws.npz',**draws);return summary,pair
if __name__=='__main__':print(json.dumps(main(),indent=2))
